import 'package:flutter/material.dart'; import 'home_page.dart'; import 'quran_page.dart'; import 'azkar_page.dart'; import 'tasbeeh_page.dart'; import 'khatma_page.dart'; import 'sleep_azkar_page.dart'; import 'prayer_times_card.dart';
class DashboardPage extends StatelessWidget { const DashboardPage({super.key}); @override Widget build(BuildContext context){ return SingleChildScrollView(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[_welcome(),const SizedBox(height:16),const PrayerTimesCard(),const SizedBox(height:16),_progress(),const SizedBox(height:16),_continue(context),const SizedBox(height:16),GridView.count(crossAxisCount:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),childAspectRatio:1.12,crossAxisSpacing:10,mainAxisSpacing:10,children:[_tile(context,Icons.menu_book,'القرآن الكريم',Colors.blue,const QuranPage()),_tile(context,Icons.favorite,'الأذكار',Colors.red,const AzkarPage()),_tile(context,Icons.fingerprint,'التسبيح',Colors.green,const TasbeehPage()),_tile(context,Icons.task_alt,'الختمة',Colors.orange,const KhatmaPage()),_tile(context,Icons.checklist,'وردي اليومي',Colors.teal,const HomePage()),_tile(context,Icons.nights_stay,'أذكار النوم',Colors.indigo,const SleepAzkarPage())]) ])); }
Widget _welcome()=>Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF0F766E),Color(0xFFD4AF37)]),borderRadius:BorderRadius.circular(24)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('السلام عليكم 🌙',style:TextStyle(color:Colors.white,fontSize:26,fontWeight:FontWeight.bold)),SizedBox(height:8),Text('مرحباً بك في وردي | Wirdi',style:TextStyle(color:Colors.white,fontSize:16))]));
Widget _progress()=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('الورد اليومي',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:12),LinearProgressIndicator(value:.65,minHeight:12,borderRadius:BorderRadius.circular(10)),const SizedBox(height:8),const Text('65% مكتمل')])));
Widget _continue(BuildContext c)=>Card(child:ListTile(leading:const CircleAvatar(backgroundColor:Colors.green,child:Icon(Icons.bookmark,color:Colors.white)),title:const Text('متابعة القراءة'),subtitle:const Text('افتح آخر موضع محفوظ في القرآن'),trailing:const Icon(Icons.arrow_forward_ios),onTap:()=>_open(c,const QuranPage())));
Widget _tile(BuildContext c,IconData icon,String title,Color color,Widget page)=>Card(child:InkWell(borderRadius:BorderRadius.circular(20),onTap:()=>_open(c,page),child:Padding(padding:const EdgeInsets.all(18),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[CircleAvatar(radius:30,backgroundColor:color.withOpacity(.15),child:Icon(icon,size:34,color:color)),const SizedBox(height:12),Text(title,textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16))]))));
void _open(BuildContext c,Widget p)=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(),body:p)))); }
